'use client';

import { useVehicle } from '@/app/axios';
import { useEffect, use, useState, useCallback } from 'react';
import { useTranslations } from 'next-intl';
import { vehicleService } from '@/app/axios/services/vehicle';
import VehicleImageGallery from '@/components/car-components/VehicleImageGallery';
import VehicleSpecsTable from '@/components/car-components/VehicleSpecsTable';
import AvailabilitySelector from '@/components/car-components/AvailabilitySelector';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { differenceInDays, parseISO } from 'date-fns';

const VehicleDetailsPage = ({ params }: { params: Promise<{ id: string }> }) => {
  const { id } = use(params);
  const { vehicle, fetchVehicleById, isLoading, error, bookingData, setBookingData } = useVehicle();
  const t = useTranslations('vehicleDetails');
  const [isChecking, setIsChecking] = useState(false);
  const [availabilityStatus, setAvailabilityStatus] = useState<boolean | null>(null);

  const checkVehicleAvailability = useCallback(
    async (start: string, end: string) => {
      if (!id) return;
      setIsChecking(true);
      try {
        const response = await vehicleService.checkAvailability(id, start, end);
        if (response.success) {
          setAvailabilityStatus(response.data?.isAvailable ?? false);
        }
      } catch (err) {
        console.error('Availability check failed', err);
      } finally {
        setIsChecking(false);
      }
    },
    [id],
  );

  useEffect(() => {
    if (id) {
      fetchVehicleById(id);
    }
  }, [fetchVehicleById, id]);

  // Auto check availability if dates are already in context (from search)
  useEffect(() => {
    if (bookingData.pickupDate && bookingData.dropoffDate && id && availabilityStatus === null) {
      checkVehicleAvailability(bookingData.pickupDate, bookingData.dropoffDate);
    }
  }, [bookingData.pickupDate, bookingData.dropoffDate, id, checkVehicleAvailability, availabilityStatus]);

  const handleServiceChange = (type: 'SELF_DRIVE' | 'CHAUFFEUR') => {
    setBookingData({ bookingType: type });
  };

  const handleDateChange = async (start: Date, end: Date) => {
    const pickupDate = start.toISOString();
    const dropoffDate = end.toISOString();

    setBookingData({ pickupDate, dropoffDate });
    checkVehicleAvailability(pickupDate, dropoffDate);
  };

  if (isLoading) {
    return (
      <div className="flex h-[60vh] items-center justify-center">
        <div className="border-primary h-12 w-12 animate-spin rounded-full border-4 border-t-transparent shadow-sm"></div>
      </div>
    );
  }

  if (error || !vehicle) {
    return (
      <div className="global-container py-20 text-center">
        <h2 className="text-2xl font-bold text-gray-800">Vehicle Not Found</h2>
        <p className="mt-2 text-gray-600">
          {error || "The vehicle you're looking for doesn't exist or has been removed."}
        </p>
      </div>
    );
  }

  const isFormValid = bookingData.pickupDate && bookingData.dropoffDate && availabilityStatus !== false;

  return (
    <main className="global-container py-8 md:py-16">
      <div className="grid grid-cols-1 gap-12 lg:grid-cols-2 lg:gap-24">
        <div className="flex flex-col gap-10">
          <VehicleImageGallery media={vehicle.media} model={vehicle.model} />
        </div>
        <div className="flex flex-col gap-8">
          <div className="flex flex-col gap-4">
            <div className="flex items-center gap-3">
              <h1 className="text-3xl font-extrabold text-gray-900">
                {vehicle.make} {vehicle.model}
              </h1>
              <div className="flex gap-2">
                <Badge className="bg-primary/30 text-foreground border-none px-3">
                  {vehicle.isAvailable ? 'Available' : 'Unavailable'}
                </Badge>
                <Badge className="text-foreground border-none bg-orange-100 px-3">{vehicle.bodyType}</Badge>
              </div>
            </div>
            <p className="text-lg font-medium text-gray-500">
              {vehicle.year} {vehicle.model} {vehicle.transmission}
            </p>
          </div>

          <AvailabilitySelector
            bookingData={bookingData}
            onServiceChange={handleServiceChange}
            onDateChange={handleDateChange}
          />

          <div className="flex flex-col gap-6">
            <div className="flex items-baseline gap-2">
              <span className="text-2xl font-extrabold text-gray-900">
                {vehicle.pricePerDay} {vehicle.currency || 'USD'}/Day
              </span>
              <span className="text-primary text-sm font-semibold">[{vehicle.depositPercentage || '35'}% Deposit]</span>
            </div>

            <Button className="w-48 rounded-md text-lg transition-all" disabled={!isFormValid || isChecking}>
              {isChecking ? 'Checking...' : 'Make Payment'}
            </Button>
          </div>
          <VehicleSpecsTable vehicle={vehicle} />
        </div>
      </div>
    </main>
  );
};

export default VehicleDetailsPage;
