'use client';

import { FC, useState } from 'react';
import { cn } from '@/lib/utils';
import { Calendar as CalendarIcon } from 'lucide-react';
import { format, addDays, isWithinInterval, parseISO, startOfDay } from 'date-fns';
import { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover';
import { Calendar } from '@/components/ui/calendar';
import { DateRange } from 'react-day-picker';

interface AvailabilitySelectorProps {
  bookingData: {
    pickupDate: string | null;
    dropoffDate: string | null;
    bookingType: 'SELF_DRIVE' | 'CHAUFFEUR';
  };
  onServiceChange: (type: 'SELF_DRIVE' | 'CHAUFFEUR') => void;
  onDateChange: (start: Date, end: Date) => void;
}

const AvailabilitySelector: FC<AvailabilitySelectorProps> = ({ bookingData, onServiceChange, onDateChange }) => {
  const [calendarOpen, setCalendarOpen] = useState(false);
  const dates = Array.from({ length: 5 }, (_, i) => addDays(new Date(), i));

  const start = bookingData.pickupDate ? startOfDay(parseISO(bookingData.pickupDate)) : null;
  const end = bookingData.dropoffDate ? startOfDay(parseISO(bookingData.dropoffDate)) : null;

  const handleDateSelect = (date: Date) => {
    onDateChange(date, date);
  };

  const handleRangeSelect = (range: DateRange | undefined) => {
    if (range?.from && range?.to) {
      onDateChange(range.from, range.to);
      setCalendarOpen(false);
    }
  };

  return (
    <div className="flex flex-col gap-6">
      <div className="flex flex-col gap-3">
        <span className="text-sm font-semibold text-gray-700">Check Availability</span>
        <div className="flex items-center gap-2">
          {dates.map((date, idx) => {
            const d = startOfDay(date);
            const isSelected = start && end && isWithinInterval(d, { start, end });

            return (
              <button
                key={idx}
                onClick={() => handleDateSelect(date)}
                className={cn(
                  'flex h-12 w-12 flex-col items-center justify-center rounded-xl border transition-all',
                  isSelected
                    ? 'border-primary bg-primary text-white'
                    : 'border-transparent bg-[#F3F4F6] text-gray-500 hover:border-gray-300',
                )}
              >
                <span className="text-[10px] font-bold uppercase">{format(date, 'dd')}</span>
                <span className="text-[10px] font-bold uppercase">{format(date, 'MMM')}</span>
              </button>
            );
          })}

          <Popover open={calendarOpen} onOpenChange={setCalendarOpen}>
            <PopoverTrigger asChild>
              <button className="flex h-12 w-12 items-center justify-center rounded-xl border-2 border-dashed border-gray-200 bg-white text-gray-400 transition-all hover:border-gray-300 hover:text-gray-500">
                <CalendarIcon className="h-5 w-5" />
              </button>
            </PopoverTrigger>
            <PopoverContent className="w-auto p-0" align="start">
              <Calendar
                initialFocus
                mode="range"
                defaultMonth={start || new Date()}
                selected={{ from: start || undefined, to: end || undefined }}
                onSelect={handleRangeSelect}
                numberOfMonths={1}
              />
            </PopoverContent>
          </Popover>
        </div>
      </div>

      <div className="flex flex-col gap-3">
        <span className="text-sm font-semibold text-gray-700">Available For</span>
        <div className="flex items-center gap-3">
          <button
            onClick={() => onServiceChange('SELF_DRIVE')}
            className={cn(
              'h-10 cursor-pointer rounded-lg border px-6 text-sm font-semibold transition-all',
              bookingData.bookingType === 'SELF_DRIVE'
                ? 'border-black bg-black text-white'
                : 'border-gray-200 bg-white text-gray-600 hover:border-gray-300',
            )}
          >
            Self Drive
          </button>
          <button
            onClick={() => onServiceChange('CHAUFFEUR')}
            className={cn(
              'h-10 cursor-pointer rounded-lg border px-6 text-sm font-semibold transition-all',
              bookingData.bookingType === 'CHAUFFEUR'
                ? 'border-black bg-black text-white'
                : 'border-gray-200 bg-white text-gray-600 hover:border-gray-300',
            )}
          >
            Chauffeur
          </button>
        </div>
      </div>
    </div>
  );
};

export default AvailabilitySelector;
